public class ValidadorCompleto {
    public static void registrarUsuario(String nombre, int edad, String email) {
        if (nombre == null) {
            throw new NullPointerException("Name cannot be null");
        }
        if (nombre.isEmpty()) {
            throw new IllegalArgumentException("Name cannot be empty");
        }
        if (edad < 0 || edad > 120) {
            throw new IllegalArgumentException("Age must be between 0 and 120, received value: " + edad);
        }
        if (email == null) {
            throw new NullPointerException("Email cannot be null");
        }
        if (!email.contains("@")) {
            throw new ArithmeticException("Email must be valid (contain @): " + email);
        }
        System.out.println("User registered: " + nombre + ", Age: " + edad + ", Email: " + email);
    }

    public static void main(String[] args) {
        String[][] usuarios = {
            {"Ana", "25", "ana@mail.com"},
            {"", "25", "test@test.com"},
            {"Bob", "-5", "bob@mail.com"},
            {"Carlos", "200", "carlos@mail.com"},
            {"Diana", "30", "null"},
            {"Eve", "22", "eve"}
        };
        for (String[] usuario : usuarios) {
            try {
                registrarUsuario(usuario[0], Integer.parseInt(usuario[1]), usuario[2]);
            } catch (NullPointerException | IllegalArgumentException | ArithmeticException e) {
                System.out.println("Validation error: " + e.getMessage());
            }
        }
    }
}
